values.value:
{
  "fields": [
    {
      "apiName": "plb_duct_folder",
      "label": "PLB Duct Details",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "Standard",
      "controllingValues": [
        "PLB Duct"
      ],
      "modalConfigsByValue": {
        "PLB Duct": {
          "title": "GENERAL DETAILS - PLB Duct",
          "modalFields": [
            {
              "id": "setup_section",
              "label": "Step 1: Configuration Setup",
              "expanded": true,
              "fields": [
                {
                  "apiName": "pipe_count",
                  "label": "Number of Line items",
                  "type": "number",
                  "colSpan": 3,
                  "defaultValue": 1,
                  "min": 1,
                  "max": 10
                },
                {
                  "apiName": "Inspection_Commission",
                  "label": "Inspection & Commission %",
                  "type": "number",
                  "colSpan": 3
                },
                {
                  "apiName": "Interest_Charges_on_Payment_type",
                  "label": "No of Days for Payment",
                  "type": "number",
                  "colSpan": 3
                },
                {
                  "apiName": "Interest_Charges_on_Payment",
                  "label": "Interest charges % per Annum",
                  "type": "number",
                  "colSpan": 3
                },
                {
                  "apiName": "Type_of_transportation",
                  "label": "Type of Transaportation",
                  "type": "picklist",
                  "required": true,
                  "options": [
                    "F.O.R (Freight on Road)",
                    "Ex-works"
                  ],
                  "pushToParentApiName": "freight_incoterms_hdpe",
                  "colSpan": 3
                },
                {
                  "apiName": "Type_of_FOR",
                  "label": "F.O.R (Freight on Road)",
                  "type": "picklist",
                  "options": [
                    "Per Meter",
                    "Lump Sum"
                  ],
                  "controllingField": "Type_of_transportation",
                  "controllingValues": [
                    "F.O.R (Freight on Road)"
                  ],
                  "colSpan": 3
                },
                {
                  "apiName": "LumpSum_Amount",
                  "label": "Lump Sum",
                  "type": "number",
                  "controllingField": "Type_of_FOR",
                  "controllingValues": [
                    "Lump Sum"
                  ],
                  "colSpan": 3
                }
              ]
            },
            {
              "id": "PE_G_and_PR_Selection_1",
              "label": "Step 2: Pipe Data Entry",
              "expanded": true,
              "controllingField": "pipe_count",
              "controllingValues": [
                ">=1"
              ],
              "fields": [
                {
                  "apiName": "vertical_pipe_grid",
                  "type": "column-repeater",
                  "countApiName": "pipe_count",
                  "maxColumns": 10,
                  "fields": [
                    {
                      "apiName": "Diameter_Size",
                      "label": "Outer/Inner Diameter Size (mm)",
                      "required": true,
                      "type": "picklist",
                      "options": [
                        "25/20",
                        "25/21",
                        "25/22",
                        "32/25",
                        "32/26",
                        "32/27",
                        "40/33 TEC Spec",
                        "40/33",
                        "50/42",
                        "63/50"
                      ]
                    },
                    {
                      "apiName": "unit_of_messurment",
                      "label": "UOM",
                      "required": true,
                      "type": "picklist",
                      "options": [
                        "mtr",
                        "Km"
                      ]
                    },
                    {
                      "apiName": "BOQ_Quantity",
                      "label": "BOQ QTY",
                      "required": true,
                      "type": "number"
                    },
                    {
                      "apiName": "len_of_coil_pipe",
                      "label": "Length of Coil (mtr)",
                      "required": true,
                      "type": "number"
                    },
                    {
                      "apiName": "No_of_Coil_Pipe",
                      "label": "No. of Coil",
                      "type": "number",
                      "readOnly": true,
                      "formula": "Math.ceil(unit_of_messurment == 'mtr' ? (BOQ_Quantity / len_of_coil_pipe) : unit_of_messurment == 'Km' ? ((BOQ_Quantity * 1000) / len_of_coil_pipe): 0)"
                    },
                    {
                      "apiName": "Weight_mtrs",
                      "label": "Weight/mtrs",
                      "type": "number",
                      "lookupWeight": true,
                      "readOnly": true,
                      "controllingFields": [
                        "Diameter_Size"
                      ],
                      "weightMap": {
                        "40/33 TEC Spec": 0.385,
                        "40/33": 0.375,
                        "50/42": 0.555,
                        "32/25": 0.301,
                        "32/26": 0.262,
                        "25/21": 0.139,
                        "25/22": 0.106,
                        "25/20": 0.17,
                        "32/27": 0.222,
                        "63/50": 1.107
                      }
                    },
                    {
                      "apiName": "final_quantity",
                      "label": "Final Quantity",
                      "type": "number",
                      "isQuantity": true,
                      "readOnly": true,
                      "formula": "(unit_of_messurment == 'mtr' ? (BOQ_Quantity) : unit_of_messurment == 'Km' ? (BOQ_Quantity * 1000): 0)"
                    },
                    {
                      "apiName": "Req_Raw_Material_in_MT",
                      "label": "Req. Raw Material in MT",
                      "required": true,
                      "readOnly": true,
                      "type": "number",
                      "formula": "(((final_quantity * Weight_mtrs) / 1000).toFixed(2))"
                    },
                    {
                      "apiName": "Realization_raw_material_conversion_cost_Kg",
                      "label": "Realization raw material+ conversion cost/ Kg",
                      "type": "number",
                      "isBasePrice": true,
                      "colSpan": 6,
                      "formula": "Realization_raw_material_conversion_cost_Kg ? Realization_raw_material_conversion_cost_Kg : plb_duct_b_rate"
                    },
                    {
                      "apiName": "Basic_Price_mtrs",
                      "label": "Basic Price/mtrs",
                      "readOnly": true,
                      "type": "number",
                      "isUnitCost": true,
                      "formula": "((Weight_mtrs*Realization_raw_material_conversion_cost_Kg).toFixed(2))"
                    },
                    {
                      "apiName": "inspectionAndCommission_Charges",
                      "label": "Inspection & Commission Rate/Mtr",
                      "readOnly": true,
                      "type": "number",
                      "formula": "((Basic_Price_mtrs * Inspection_Commission)/100).toFixed(2)"
                    },
                    {
                      "apiName": "Fittings_Charges",
                      "label": "Pulling Rope / Mtr",
                      "type": "number"
                    },
                    {
                      "apiName": "Freight_including_Unloading_mtrs",
                      "label": "Freight Charges/Mtr",
                      "type": "number",
                      "disableControllingField": "Type_of_FOR",
                      "disableControllingValues": [
                        "Per Meter"
                      ]
                    },
                    {
                      "apiName": "Interest_Charges",
                      "label": "Interest Charges/Mtr",
                      "type": "number",
                      "readOnly": true,
                      "formula": "(((Basic_Price_mtrs+Fittings_Charges+Freight_including_Unloading_mtrs+((Basic_Price_mtrs*Inspection_Commission)/100))*(1+GST/100))*Interest_Charges_on_Payment*(Interest_Charges_on_Payment_type/365)/100).toFixed(2)"
                    },
                    {
                      "apiName": "FOR_Price",
                      "label": "F.O.R. Price including Inspection, Interest Charges, BG / meter",
                      "type": "number",
                      "isListPrice": true,
                      "readOnly": true,
                      "formula": "((Basic_Price_mtrs+Fittings_Charges+Freight_including_Unloading_mtrs+((Basic_Price_mtrs*Inspection_Commission)/100))+ Interest_Charges).toFixed(2)"
                    },
                    {
                      "apiName": "GST",
                      "label": "GST  %",
                      "type": "number",
                      "readOnly": true,
                      "formula": "plb_duct_gst"
                    },
                    {
                      "apiName": "Total_Per_Mtr",
                      "label": "Total Per Mtr",
                      "type": "number",
                      "isUnitPrice": true,
                      "readOnly": true,
                      "formula": "((FOR_Price + (FOR_Price*GST)/100).toFixed(4))"
                    },
                    {
                      "apiName": "Total_Amount",
                      "label": "Total Amount",
                      "type": "number",
                      "readOnly": true,
                      "formula": "((FOR_Price * final_quantity) * (1 + GST / 100)).toFixed(2)"
                    }
                  ]
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
